WITH f AS MATERIALIZED(SELECT id_resultado,id_evento,data_evento FROM estudo.fat_perfil_br_2026_20261109),
summary AS(SELECT count(*) AS rows,count(DISTINCT id_resultado) AS unique_ids,count(DISTINCT id_evento) AS events,count(*) FILTER(WHERE id_resultado IS NULL) AS null_ids,min(data_evento) AS first_date,max(data_evento) AS last_date,count(*) FILTER(WHERE data_evento IS NULL OR data_evento<DATE '2026-01-01' OR data_evento>=DATE '2026-10-01') AS outside_window FROM f),
months AS(SELECT date_trunc('month',data_evento)::date AS month,count(*) AS rows FROM f GROUP BY 1),
view_counts AS(SELECT 'estudo.vwbi_perfil_br_2026' AS name,count(*) AS rows FROM estudo.vwbi_perfil_br_2026 UNION ALL SELECT 'estudo.vw_resultados_2026',count(*) FROM estudo.vw_resultados_2026 UNION ALL SELECT 'public.tbbi_fat_perfil_br_2026',count(*) FROM public.tbbi_fat_perfil_br_2026)
SELECT jsonb_build_object('capturado_em',transaction_timestamp(),'read_only',current_setting('transaction_read_only'),'timeout',current_setting('statement_timeout'),'fact',(SELECT to_jsonb(s) FROM summary s),'months',(SELECT jsonb_agg(to_jsonb(m) ORDER BY month) FROM months m),'counts',(SELECT jsonb_agg(to_jsonb(v)) FROM view_counts v))::text AS payload